-- Case syndication-shared: PhotoInfo.Syndicated, SavedToLibrary and Shared.
-- Changes: the asset marked mig:syndicated-not-saved gets ZSYNDICATIONIDENTIFIER TEST-SYND-0001 and
-- ZSYNDICATIONHISTORY 0; mig:syndicated-saved gets TEST-SYND-0002 and ZSYNDICATIONHISTORY NULL;
-- mig:shared-album-photo gets ZASSET.ZCLOUDBATCHPUBLISHDATE 694224000 (2023-01-01T00:00:00Z).
-- Expects: not-saved: Syndicated true, SavedToLibrary false; saved: Syndicated true, SavedToLibrary true
-- (NULL history counts as saved, as upstream); shared-album-photo: Shared true.

UPDATE ZADDITIONALASSETATTRIBUTES
SET ZTITLE = 'mig:syndicated-not-saved', ZSYNDICATIONIDENTIFIER = 'TEST-SYND-0001', ZSYNDICATIONHISTORY = 0
WHERE Z_PK = (SELECT x.Z_PK FROM ZADDITIONALASSETATTRIBUTES x JOIN ZASSET a ON a.Z_PK = x.ZASSET
              WHERE (x.ZTITLE IS NULL OR x.ZTITLE NOT LIKE 'mig:%')
                AND a.ZTRASHEDSTATE = 0 AND a.ZAVALANCHEUUID IS NULL
              ORDER BY a.ZUUID LIMIT 1);

UPDATE ZADDITIONALASSETATTRIBUTES
SET ZTITLE = 'mig:syndicated-saved', ZSYNDICATIONIDENTIFIER = 'TEST-SYND-0002', ZSYNDICATIONHISTORY = NULL
WHERE Z_PK = (SELECT x.Z_PK FROM ZADDITIONALASSETATTRIBUTES x JOIN ZASSET a ON a.Z_PK = x.ZASSET
              WHERE (x.ZTITLE IS NULL OR x.ZTITLE NOT LIKE 'mig:%')
                AND a.ZTRASHEDSTATE = 0 AND a.ZAVALANCHEUUID IS NULL
              ORDER BY a.ZUUID LIMIT 1);

UPDATE ZADDITIONALASSETATTRIBUTES SET ZTITLE = 'mig:shared-album-photo'
WHERE Z_PK = (SELECT x.Z_PK FROM ZADDITIONALASSETATTRIBUTES x JOIN ZASSET a ON a.Z_PK = x.ZASSET
              WHERE (x.ZTITLE IS NULL OR x.ZTITLE NOT LIKE 'mig:%')
                AND a.ZTRASHEDSTATE = 0 AND a.ZAVALANCHEUUID IS NULL
              ORDER BY a.ZUUID LIMIT 1);

UPDATE ZASSET SET ZCLOUDBATCHPUBLISHDATE = 694224000
WHERE Z_PK = (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES WHERE ZTITLE = 'mig:shared-album-photo');
